-- +goose Up
-- The Workspace's sending rules (ADR 0134, ADR 0137): its Frequency caps and its Sending windows,
-- one row per Channel and country. The tables are new and empty, so their indexes are built with
-- them; then every Workspace not erased gets the rows a new one starts with (Creation.CreateIn): at
-- most three marketing texts per 1440 minutes to one number, and an SMS window of 8:00 to 20:00
-- every day. A few rows per Workspace, so they are written here rather than by a job.
-- create "frequency_caps" table
CREATE TABLE "frequency_caps" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "channel" character varying NOT NULL, "country" character varying NULL, "max_messages" bigint NULL, "period_minutes" bigint NULL, "workspace_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "frequency_caps_workspaces_frequency_caps" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "frequency_caps_cap_check" CHECK ((max_messages IS NULL) = (period_minutes IS NULL)), CONSTRAINT "frequency_caps_channel_check" CHECK ((channel)::text = ANY ((ARRAY['email'::character varying, 'telegram'::character varying, 'sms'::character varying])::text[])), CONSTRAINT "frequency_caps_country_check" CHECK ((country IS NULL) OR ((channel)::text = 'sms'::text)), CONSTRAINT "frequency_caps_country_format" CHECK ((country)::text ~ '^[A-Z]{2}$'::text), CONSTRAINT "frequency_caps_max_messages_check" CHECK (max_messages >= 1), CONSTRAINT "frequency_caps_period_minutes_check" CHECK ((period_minutes >= 1) AND (period_minutes <= 10080)));
-- create index "frequency_caps_workspace_channel_country" to table: "frequency_caps"
CREATE UNIQUE INDEX "frequency_caps_workspace_channel_country" ON "frequency_caps" ("workspace_id", "channel", "country") NULLS NOT DISTINCT;
-- create "sending_windows" table
CREATE TABLE "sending_windows" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "channel" character varying NOT NULL, "country" character varying NULL, "monday_opens" bigint NULL, "monday_closes" bigint NULL, "tuesday_opens" bigint NULL, "tuesday_closes" bigint NULL, "wednesday_opens" bigint NULL, "wednesday_closes" bigint NULL, "thursday_opens" bigint NULL, "thursday_closes" bigint NULL, "friday_opens" bigint NULL, "friday_closes" bigint NULL, "saturday_opens" bigint NULL, "saturday_closes" bigint NULL, "sunday_opens" bigint NULL, "sunday_closes" bigint NULL, "workspace_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "sending_windows_workspaces_sending_windows" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "sending_windows_channel_check" CHECK ((channel)::text = ANY ((ARRAY['email'::character varying, 'telegram'::character varying, 'sms'::character varying])::text[])), CONSTRAINT "sending_windows_country_format" CHECK ((country)::text ~ '^[A-Z]{2}$'::text), CONSTRAINT "sending_windows_friday_check" CHECK (((friday_opens IS NULL) = (friday_closes IS NULL)) AND (friday_opens >= 0) AND (friday_opens < friday_closes) AND (friday_closes <= 1440)), CONSTRAINT "sending_windows_monday_check" CHECK (((monday_opens IS NULL) = (monday_closes IS NULL)) AND (monday_opens >= 0) AND (monday_opens < monday_closes) AND (monday_closes <= 1440)), CONSTRAINT "sending_windows_opens_check" CHECK ((monday_opens IS NOT NULL) OR (tuesday_opens IS NOT NULL) OR (wednesday_opens IS NOT NULL) OR (thursday_opens IS NOT NULL) OR (friday_opens IS NOT NULL) OR (saturday_opens IS NOT NULL) OR (sunday_opens IS NOT NULL)), CONSTRAINT "sending_windows_phone_channel_check" CHECK ((channel)::text = 'sms'::text), CONSTRAINT "sending_windows_saturday_check" CHECK (((saturday_opens IS NULL) = (saturday_closes IS NULL)) AND (saturday_opens >= 0) AND (saturday_opens < saturday_closes) AND (saturday_closes <= 1440)), CONSTRAINT "sending_windows_sunday_check" CHECK (((sunday_opens IS NULL) = (sunday_closes IS NULL)) AND (sunday_opens >= 0) AND (sunday_opens < sunday_closes) AND (sunday_closes <= 1440)), CONSTRAINT "sending_windows_thursday_check" CHECK (((thursday_opens IS NULL) = (thursday_closes IS NULL)) AND (thursday_opens >= 0) AND (thursday_opens < thursday_closes) AND (thursday_closes <= 1440)), CONSTRAINT "sending_windows_tuesday_check" CHECK (((tuesday_opens IS NULL) = (tuesday_closes IS NULL)) AND (tuesday_opens >= 0) AND (tuesday_opens < tuesday_closes) AND (tuesday_closes <= 1440)), CONSTRAINT "sending_windows_wednesday_check" CHECK (((wednesday_opens IS NULL) = (wednesday_closes IS NULL)) AND (wednesday_opens >= 0) AND (wednesday_opens < wednesday_closes) AND (wednesday_closes <= 1440)));
-- create index "sending_windows_workspace_channel_country" to table: "sending_windows"
CREATE UNIQUE INDEX "sending_windows_workspace_channel_country" ON "sending_windows" ("workspace_id", "channel", "country") NULLS NOT DISTINCT;

-- give every Workspace the SMS Frequency cap a new one starts with
INSERT INTO "frequency_caps" ("workspace_id", "channel", "max_messages", "period_minutes")
SELECT "id", 'sms', 3, 1440 FROM "workspaces" WHERE "erased_at" IS NULL;
-- give every Workspace the SMS Sending window a new one starts with
INSERT INTO "sending_windows" ("workspace_id", "channel", "monday_opens", "monday_closes", "tuesday_opens", "tuesday_closes", "wednesday_opens", "wednesday_closes", "thursday_opens", "thursday_closes", "friday_opens", "friday_closes", "saturday_opens", "saturday_closes", "sunday_opens", "sunday_closes")
SELECT "id", 'sms', 480, 1200, 480, 1200, 480, 1200, 480, 1200, 480, 1200, 480, 1200, 480, 1200 FROM "workspaces" WHERE "erased_at" IS NULL;

-- +goose Down
-- reverse: create index "sending_windows_workspace_channel_country" to table: "sending_windows"
DROP INDEX "sending_windows_workspace_channel_country";
-- reverse: create "sending_windows" table
DROP TABLE "sending_windows";
-- reverse: create index "frequency_caps_workspace_channel_country" to table: "frequency_caps"
DROP INDEX "frequency_caps_workspace_channel_country";
-- reverse: create "frequency_caps" table
DROP TABLE "frequency_caps";
